function getCategory(name) {
  if (!name) return 'other';
  if (SERVICE_CATEGORY_MAP[name]) return SERVICE_CATEGORY_MAP[name];
  const n = name.toLowerCase();
  if (n.includes('temizlik') || n.includes('temizliği') || n.includes('yıkama')) return 'cleaning';
  if (n.includes('masaj') || n.includes('ağda') || n.includes('güzellik') || n.includes('manikür')) return 'beauty';
  if (n.includes('tamir') || n.includes('montaj') || n.includes('boya') || n.includes('tesisat') || n.includes('elektrik')) return 'repair';
  if (n.includes('nakliy') || n.includes('taşıma') || n.includes('transfer') || n.includes('hamal')) return 'moving';
  if (n.includes('ders') || n.includes('kurs') || n.includes('eğitim')) return 'education';
  return 'other';
}

