function buildEvents() {
  const allRaw = [
    ...RAW_JOBS.map(j => ({ ...j, type: 'job' })),
    ...RAW_REVIEWS.map(r => ({ ...r, type: 'review' })),
  ].filter(e => e.lat && e.lng)
   .sort((a, b) => new Date(a.ts) - new Date(b.ts));

  const t0   = new Date(allRaw[0].ts).getTime();
  const tEnd = new Date(allRaw[allRaw.length - 1].ts).getTime();
  const span = tEnd - t0;
  const SIM_DUR = 600000;

  const events = [];
  for (const e of allRaw) {
    const timestamp = Math.round((new Date(e.ts).getTime() - t0) / span * SIM_DUR);
    const category  = getCategory(e.service);

    if (e.type === 'job') {
      const pos = proPosition(e.id, e.lat, e.lng);
      events.push({
        id:              'job_' + e.id,
        type:            'job',
        timestamp,
        customerLat:     e.lat,
        customerLng:     e.lng,
        proLat:          pos.lat,
        proLng:          pos.lng,
        serviceName:     e.service,
        serviceCategory: category,
        proName:         '',
        arcDuration:     1200,
        arcFadeDelay:    0,
      });
    } else {
      events.push({
        id:              'rev_' + e.id,
        type:            'review',
        timestamp,
        lat:             e.lat,
        lng:             e.lng,
        rating:          e.rating,
        reviewText:      e.text,
        proName:         '',
        serviceName:     e.service,
        serviceCategory: category,
        popDuration:     5500,
      });
    }
  }

  return { events, simStart: t0, simEnd: tEnd };
}

const _istanbul = buildEvents();
export const EVENTS                = _istanbul.events;
export const SIM_DURATION          = 600000;

// Named exports for city-switching
export const ISTANBUL_EVENTS       = _istanbul.events;
export const ISTANBUL_SIM_DURATION = SIM_DURATION;
export const ISTANBUL_SIM_START    = _istanbul.simStart;
export const ISTANBUL_SIM_END      = _istanbul.simEnd;
